      params: [
        ToolParam(name: 'path', description: 'Path to check'),
      ],
    );

/// `file_delete` — delete a file.
ToolDefinition _deleteTool() => ToolDefinition(
      name: 'file_delete',
      description: 'Delete a file',
      integration: 'file',
