        ToolParam(name: 'path', description: 'Path of the file to delete'),
      ],
    );

/// `file_copy` — copy a file from source to destination.
ToolDefinition _copyTool() => ToolDefinition(
      name: 'file_copy',
      description: 'Copy a file from source to destination',
