      category: 'filesystem',
      params: [
        ToolParam(name: 'path', description: 'File path to read'),
      ],
    );

/// `file_write` — write content to a file, creating or overwriting it.
ToolDefinition _writeTool() => ToolDefinition(
      name: 'file_write',
