        ToolParam(name: 'content', description: 'The text content to write'),
      ],
    );

/// `file_list` — list entries in a directory.
ToolDefinition _listTool() => ToolDefinition(
      name: 'file_list',
      description: 'List entries in a directory',
      integration: 'file',
      category: 'filesystem',
      params: [
