/// `file_read_json` — read a file and parse it as JSON.
ToolDefinition _readJsonTool() => ToolDefinition(
      name: 'file_read_json',
      description: 'Read a file and parse it as JSON',
      integration: 'file',
      category: 'filesystem',
      params: [
        ToolParam(name: 'path', description: 'File path to read'),
