  /// before the call; this closes the pair so slow calls (tracker
  /// hydration, CLI, HTTP) are visible in the plain trace.
  String _timed(String toolName, String Function() run) {
    final sw = Stopwatch()..start();
    try {
      return run();
    } finally {
